:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1c1a17;
  --muted: #5c5750;
  --line: #ddd8d0;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --selected: #ecfdf5;
  --radius: 10px;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181a;
    --surface: #1f2225;
    --ink: #eceae6;
    --muted: #a9a49c;
    --line: #34383c;
    --accent: #2dd4bf;
    --accent-ink: #10201e;
    --selected: #16302c;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 62rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  padding: 0.5rem 0.85rem;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0 0 var(--radius) 0;
}

.skip-link:focus {
  left: 0;
  z-index: 10;
}

.masthead h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -0.01em;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

.columns {
  display: grid;
  gap: 1.5rem;
  grid-template-columns: minmax(0, 20rem) minmax(0, 1fr);
  align-items: start;
}

@media (max-width: 48rem) {
  .columns {
    grid-template-columns: minmax(0, 1fr);
  }
}

h2 {
  font-size: 1.05rem;
  margin: 0 0 0.75rem;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0 0 0.9rem;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.45rem 0.55rem;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 6rem;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

[aria-invalid='true'] {
  border-color: #b91c1c;
}

.hint {
  font-size: 0.8rem;
  color: var(--muted);
}

.hint code {
  font-size: 0.95em;
}

button[type='submit'] {
  font: inherit;
  font-weight: 600;
  background: var(--accent);
  color: var(--accent-ink);
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 0.5rem 1rem;
  cursor: pointer;
}

button[type='submit']:hover {
  filter: brightness(1.08);
}

.form-message:empty {
  display: none;
}

.form-message {
  margin: 0 0 0.75rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.search-panel {
  margin-bottom: 1.5rem;
}

.search-panel .field {
  margin-bottom: 0.5rem;
}

.results-line {
  margin: 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.results-line:empty {
  display: none;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: var(--radius);
  padding: 0.9rem 1rem;
}

.note[aria-current='true'] {
  border-left-color: var(--accent);
  background: var(--selected);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  flex: none;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
}

.note-title {
  flex: 1;
  margin: 0;
  font-size: 1.05rem;
}

.note-title-button {
  font: inherit;
  color: inherit;
  display: block;
  width: 100%;
  text-align: left;
  background: none;
  border: 0;
  border-radius: 4px;
  padding: 0.1rem 0;
  cursor: pointer;
}

.note-title-button:hover {
  color: var(--accent);
}

.note-body {
  margin-top: 0.4rem;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-time {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.78rem;
  color: var(--muted);
}

.feed-empty,
.feed-hidden-selection {
  margin: 0;
  padding: 0.75rem 0;
  color: var(--muted);
  font-size: 0.9rem;
}

