#!/usr/bin/env node
// Temporary contract check — not part of the deliverable.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = import.meta.dirname;
const port = 4800 + Math.floor(Math.random() * 500);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

let failures = 0;
const errors = [];
function check(name, ok, detail = '') {
  if (!ok) failures++;
  console.log(`${ok ? 'ok  ' : 'FAIL'}  ${name}${ok || !detail ? '' : `  -> ${detail}`}`);
}

const browser = await chromium.launch();
const page = await browser.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => m.type() === 'error' && errors.push('console: ' + m.text()));
page.on('dialog', async (d) => { errors.push('DIALOG: ' + d.message()); await d.dismiss(); });

// ---- seed + feed order
await page.goto(base, { waitUntil: 'load' });
const ids = await page.$$eval('#feed article.note', (ns) => ns.map((n) => n.dataset.noteId));
